args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate WHERE {
  VALUES ?film { dbr:Three_Violent_People dbr:Girls_in_White }
  { ?film dbo:director ?director } UNION { ?film dbp:director ?director } .
  OPTIONAL { ?director dbo:deathDate ?deathDate1. }
  OPTIONAL { ?director dbp:deathDate ?deathDate2. }
  OPTIONAL { ?director dbp:death_date ?deathDate3. }
  BIND(coalesce(?deathDate1, ?deathDate2, ?deathDate3) AS ?deathDate)
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel)='en') }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel)='en') }
}
ORDER BY ?deathDate
LIMIT 1

